import sys
from collections import defaultdict

def rotate_piece(piece):
    return [''.join(row[i] for row in piece) for i in range(len(piece[0]))]

def get_piece(picture, x, y, i, j):
    return [picture[x_start][j:j+y] for x_start in range(i, i+x)]

def is_good_puzzle(picture, x, y):
    pieces = defaultdict(int)
    for i in range(0, len(picture), x):
        for j in range(0, len(picture[0]), y):
            piece = get_piece(picture, x, y, i, j)
            rotations = {tuple(r) for r in [piece, rotate_piece(piece)]}
            for rot in rotations:
                pieces[rot] += 1
                if pieces[rot] > 1:
                    return False
    return True

def main():
    import sys
    input = sys.stdin.read().splitlines()
    A, B = map(int, input[0].split())
    picture = input[1:A+1]
    good_puzzles = []
    for x in range(1, A+1):
        if A % x != 0:
            continue
        for y in range(1, B+1):
            if B % y != 0:
                continue
            if is_good_puzzle(picture, x, y):
                good_puzzles.append((x, y))
    print(len(good_puzzles))
    print(min(good_puzzles, key=lambda z: (z[0]*z[1], z[0])))

main()
